import { Table, BooleanColumn, GuidColumn, StringColumn } from '@servicenow/sdk/core'

export const sys_mailbox = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Mailboxes',
    name: 'sys_mailbox',
    schema: {
        system_mailbox: BooleanColumn({
            default: false,
            label: 'System mailbox',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        name: StringColumn({
            label: 'Name',
        }),
    },
    textIndex: true,
})
